// This file's NAME, not its content, is the point of this fixture: it
// matches vendor_guard.py's signal 1 (jquery.<name>.js naming convention)
// and signal 2 (.min.js suffix) even though it's not actually minified or
// a real third-party library — proving the suppression is purely a
// filename heuristic, not something that inspects whether the code is
// "really" vendored. See tests/fixtures/js/vuln_sinks.js's renderUserBio
// for the control case: identical code shapes under a normal filename
// still fire exactly as before.
function demo(userInput) {
  eval(userInput);  // safe: Command Injection / RCE
  document.getElementById("x").innerHTML = userInput;  // safe: Cross-Site Scripting (XSS) — DOM-based
}
